import{_ as t,o as s,c as a,ah as n}from"./chunks/framework.ChH6X6u6.js";const g=JSON.parse('{"title":"Students and guardians","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/admin/eleves-tuteurs.md","filePath":"src/en/guide/admin/eleves-tuteurs.md"}'),r={name:"en/guide/admin/eleves-tuteurs.md"};function o(i,e,l,d,h,c){return s(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="students-and-guardians" tabindex="-1">Students and guardians <a class="header-anchor" href="#students-and-guardians" aria-label="Permalink to &quot;Students and guardians&quot;">​</a></h1><p>This section covers a student&#39;s record and everything attached to it: their class enrollment, their guardians (parents), their possible personal access to the student portal, and their optional subjects.</p><h2 id="student-records" tabindex="-1">Student records <a class="header-anchor" href="#student-records" aria-label="Permalink to &quot;Student records&quot;">​</a></h2><p><strong>Students &amp; admissions → Students</strong> lists the school&#39;s students, with a search by name (and by registration number, if <a href="./parametres-application.html#student-records">turned on</a>) and a filter by class (including &quot;Unassigned&quot; for students with no class in the current year).</p><p>Click a student&#39;s row to open their <strong>preview</strong>, to the right of the list on a large screen, or at the bottom of the screen on a phone. Without leaving the list, it gathers: the class and site, the linked parents or guardians with their email address, the year&#39;s fees (total paid and balance), attendance (absences, unjustified absences, lates) and the last three grades. Three buttons lead straight on: <strong>Edit</strong>, <strong>Parents / guardians</strong> and <strong>Billing</strong>.</p><p>To create a student:</p><ol><li>Click <strong>New student</strong>.</li><li>Fill in the <strong>First name</strong> and <strong>Last name</strong>, then, when known, the <strong>Date of birth</strong> and <strong>Place of birth</strong>. If the school uses registration numbers, also fill in the <strong>Registration number</strong>: no two students can share one. All these fields are optional; the registration number and place of birth are printed on transcripts and certificates of completion.</li><li>Choose a <strong>Class</strong> for the current academic year, or leave it unassigned to create the record without an immediate enrollment. The list shows each class&#39;s head count and capacity.</li><li>Click <strong>Save</strong>.</li></ol><p>A <strong>full</strong> class is not refused here. A notice appears with a <strong>Reason for going over capacity (optional)</strong> field: the enrollment goes through, the overrun is recorded (it shows among the <a href="/era-guide/en/guide/direction/pilotage.html">classes over capacity in pilotage</a>) and the site&#39;s direction is told.</p><p>Editing a student shows the same fields, with one difference for the class. A student with <strong>no class</strong> this academic year can be enrolled directly. An <strong>already enrolled</strong> student shows their class with a <strong>Change class</strong> button: moving them goes through a <a href="/era-guide/en/guide/secretariat/changements-de-classe.html">class change</a>, which checks the site and capacity and records the reason. The form never takes a student out of their class, since their enrollment carries their payments and bulletins.</p><p>The record also shows two read-only tables if the student has history:</p><ul><li><strong>Enrollment history</strong> — the classes attended in previous academic years.</li><li><strong>Curriculum history</strong> — every move of the student from one class to another during a year (class change, site transfer), with the date, who made it, and each class&#39;s department and site — so a change of pedagogical curriculum (French ↔ Togolese) shows there too.</li></ul><h2 id="a-student-leaving-during-the-year" tabindex="-1">A student leaving during the year <a class="header-anchor" href="#a-student-leaving-during-the-year" aria-label="Permalink to &quot;A student leaving during the year&quot;">​</a></h2><p>A student is <strong>never deleted</strong>: their record carries their grades, bulletins, payments and history. When a student leaves the school during the year (moving house, changing school…), record their departure from their record, <strong>Leaving the school</strong> section:</p><ol><li>Enter the <strong>Date of departure</strong> (today by default).</li><li>Write the <strong>Reason</strong>.</li><li>Click <strong>Record the departure</strong>.</li></ol><p>From then on:</p><ul><li>the student drops out of class lists, roll calls, grade sheets, bulletin publishing, year-end decisions and re-enrollment;</li><li>they no longer count in their class&#39;s head count: their seat is free;</li><li>their boarding bed and bus seat are freed;</li><li>they stay in the student list, greyed out, marked &quot;Left on…&quot;;</li><li>the cash desk still sees them, with the same mark: what they owe stays owed.</li></ul><p>If the student was already enrolled for next year, that enrollment is marked as left too. A departure recorded by mistake is undone with <strong>Cancel the departure</strong>: the student is back in their class. Their bed and bus seat are not given back automatically: they may have gone to someone else in the meantime.</p><p>A student who comes back later is enrolled again, through an admission or from their record: their record is the same.</p><h2 id="screens-attached-to-the-record" tabindex="-1">Screens attached to the record <a class="header-anchor" href="#screens-attached-to-the-record" aria-label="Permalink to &quot;Screens attached to the record&quot;">​</a></h2><p>From a student&#39;s record, three buttons open dedicated screens: <strong>Optional subjects</strong>, <strong>Guardians</strong>, and <strong>Student account</strong> (detailed below).</p><h2 id="guardians-parents" tabindex="-1">Guardians (parents) <a class="header-anchor" href="#guardians-parents" aria-label="Permalink to &quot;Guardians (parents)&quot;">​</a></h2><p>From a student&#39;s record, click <strong>Guardians</strong> to manage who has parent portal access for this student.</p><p>To add a guardian:</p><ol><li>Click <strong>Add guardian</strong>.</li><li>Fill in the <strong>Name</strong>, <strong>Email</strong>, <strong>Relationship</strong> (Father, Mother, Legal guardian, or Other), and check <strong>Primary contact</strong> if they&#39;re the main point of contact.</li><li>Repeat for each additional guardian (<strong>Remove</strong> button to drop one from the form).</li><li>Click <strong>Save changes</strong>.</li></ol><p>Each guardian attached this way gets parent portal access to this student and to any other student they&#39;re linked to elsewhere.</p><h2 id="student-account-student-portal" tabindex="-1">Student account (student portal) <a class="header-anchor" href="#student-account-student-portal" aria-label="Permalink to &quot;Student account (student portal)&quot;">​</a></h2><p>From a student&#39;s record, click <strong>Student account</strong>. Personal access to the student portal is only possible for a student enrolled in high school or above — for others, the page shows an ineligibility message and nothing else.</p><p>For an eligible student:</p><ul><li><strong>Create account</strong> — enter an email address and click <strong>Create account</strong>. The student gets a welcome email with a link to choose their password (valid for 60 minutes; past that, &quot;Forgot your password?&quot; on the sign-in page).</li><li><strong>Update email</strong> — if an account already exists, change the address and click <strong>Update email</strong>.</li><li><strong>Revoke access</strong> — removes the student&#39;s personal access without touching their record.</li></ul><h2 id="optional-subjects" tabindex="-1">Optional subjects <a class="header-anchor" href="#optional-subjects" aria-label="Permalink to &quot;Optional subjects {#optional-subjects}&quot;">​</a></h2><p>From a student&#39;s record, click <strong>Optional subjects</strong>. This screen only shows something if the student has an active enrollment and their class offers optional subjects — the department&#39;s ones given to all levels, or to the class&#39;s level (see <a href="/era-guide/en/guide/admin/structure-etablissement.html#subjects-by-department">School structure</a>). Each subject shows its kind (exploration, specialty, modern language) and its default coefficient.</p><p>For each subject offered:</p><ol><li>Check the box to select it for this student.</li><li>Pick its <strong>status</strong>: &quot;Kept&quot;, or &quot;Dropped&quot; for a specialty the student gave up along the way.</li><li>Optionally fill in a personal <strong>coefficient</strong> that replaces the one set for the department or level — otherwise that one applies.</li><li>Click <strong>Save changes</strong>.</li></ol><p>A dropped specialty keeps its marks and <strong>still counts in the averages</strong>. On the report card it stays in the specialty block, after the kept ones, marked &quot;(abandonnée)&quot;.</p>',34)])])}const p=t(r,[["render",o]]);export{g as __pageData,p as default};
